 AS `txBatteryStatus`, SUM(a.`consBatteryVoltage` IS NOT NULL) AS `consBatteryVoltage`, SUM(a.`hail` IS NOT NULL) AS `hail`, SUM(a.`hailRate` IS NOT NULL) AS `hailRate`, SUM(a.`heatingTemp` IS NOT NULL) AS `heatingTemp`, SUM(a.`heatingVoltage` IS NOT NULL) AS `heatingVoltage`, SUM(a.`supplyVoltage` IS NOT NULL) AS `supplyVoltage`, SUM(a.`referenceVoltage` IS NOT NULL) AS `referenceVoltage`, SUM(a.`windBatteryStatus` IS NOT NULL) AS `windBatteryStatus`, SUM(a.`rainBatteryStatus` IS NOT NULL) AS `rainBatteryStatus`, SUM(a.`outTempBatteryStatus` IS NOT NULL) AS `outTempBatteryStatus`, SUM(a.`inTempBatteryStatus` IS NOT NULL) AS `inTempBatteryStatus` FROM `old_weewx`.archive a LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime WHERE a.dateTime>=UNIX_TIMESTAMP('2009-01-01') AND a.dateTime<UNIX_TIMESTAMP('2021-01-01') AND r.dateTime IS NULL GROUP BY YEAR(FROM_UNIXTIME(a.dateTime))
